begin;
update public.dining_tables set status='fechada' where status='aberta';
update public.cash_sessions set status='CLOSED' where status='OPEN';
do $$begin perform set_config('request.jwt.claim.sub',(select id::text from auth.users where lower(email)='dejandrea@gmail.com'),true);end $$;
set local role authenticated;
do $$
declare baseline numeric; funded uuid; acc uuid:=gen_random_uuid();bank uuid:=gen_random_uuid();cat uuid:=gen_random_uuid();cash uuid:=gen_random_uuid();pix uuid:=gen_random_uuid();credit uuid:=gen_random_uuid();
 session uuid:=gen_random_uuid();session2 uuid:=gen_random_uuid();cmd uuid:=gen_random_uuid();cmd2 uuid:=gen_random_uuid();cmd3 uuid:=gen_random_uuid();cmd4 uuid:=gen_random_uuid();
 customer integer;tab public.dining_tables;data jsonb;opening jsonb;sale public.cash_sales;sale2 public.cash_sales;result jsonb;request uuid;debit uuid;receipt uuid;payment uuid;newcmd uuid;
begin
 perform public.finance_config('accounts',acc,jsonb_build_object('nome','Fixture full cash','tipo','CASH','ativo',true,'saldo_inicial',100,'data',(now() at time zone 'America/Bahia')::date));
 perform public.finance_config('accounts',bank,jsonb_build_object('nome','Fixture cash bank','tipo','BANK','ativo',true,'saldo_inicial',200,'data',(now() at time zone 'America/Bahia')::date));
 perform public.finance_config('categories',cat,'{"nome":"Fixture full cash revenue","natureza":"INCOME","ativo":true}');
 perform public.finance_config('methods',cash,'{"nome":"Fixture cash method","tipo":"CASH","ativo":true,"usar_pdv":false,"prazo_dias":0,"max_parcelas":1}');
 perform public.finance_config('methods',pix,'{"nome":"Fixture full cash pix","tipo":"PIX","ativo":true,"usar_pdv":false,"prazo_dias":0,"max_parcelas":1}'||jsonb_build_object('conta_padrao_id',(select id from public.financial_accounts where caixa_padrao)));
 perform public.finance_config('methods',credit,'{"nome":"Fixture full cash deferred","tipo":"DEFERRED","ativo":true,"usar_pdv":false,"prazo_dias":30,"max_parcelas":1}');
 funded:=acc;
 select id into acc from public.financial_accounts where caixa_padrao;
 select coalesce(sum(valor),0) into baseline from public.financial_entries where conta_id=acc;
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','TRANSFER','valor',100,'data',(now() at time zone 'America/Bahia')::date,'descricao','Fixture cash funding','conta_id',funded,'destino_id',acc));
 opening:=jsonb_build_object('conta_id',acc,'categoria_id',cat,'valor_abertura',100);
 begin perform public.cash_operation(session,'OPEN',opening||jsonb_build_object('valor_abertura',101+greatest(baseline,0)));raise exception 'FAIL: opening exceeds financial balance';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.cash_operation(session,'OPEN',opening);perform public.cash_operation(session,'OPEN',opening);
 if not (select cash=any(method_ids) and pix=any(method_ids) and credit=any(method_ids) from public.cash_sessions where id=session) then raise exception 'Not all active methods enabled';end if;
 data:=jsonb_build_object('request_id',gen_random_uuid(),'valor',150,'conta_id',bank,'motivo','Retirada teste');
 begin perform public.cash_operation(session,'WITHDRAW',data);raise exception 'FAIL: excessive withdrawal';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:=jsonb_build_object('request_id',gen_random_uuid(),'valor',25,'conta_id',bank,'motivo','Retirada teste');
 perform public.cash_operation(session,'WITHDRAW',data);perform public.cash_operation(session,'WITHDRAW',data);
 data:=jsonb_build_object('request_id',gen_random_uuid(),'valor',10,'conta_id',bank,'motivo','Troco adicional');
 perform public.cash_operation(session,'SUPPLY',data);
 result:=public.cash_dashboard();
 if (select (v->>'expected_cash')::numeric from jsonb_array_elements(result) v where v->>'id'=session::text)<>85 then raise exception 'Wrong physical balance';end if;
 insert into public.customers(nome,limite) values('Fixture full cash customer',1000) returning codigo_cliente into customer;
 perform public.comanda_operation(cmd,'OPEN',jsonb_build_object('identificacao','Fixture venda um','customer_codigo',customer));
 select * into tab from public.dining_tables where id=cmd;
 insert into public.dining_table_items(codigo_mesa,descricao,valor_unitario,quantidade) values(tab.codigo_mesa,'Consumo',10,5);
 data:=jsonb_build_object('request_id',gen_random_uuid(),'total',50,'payments',jsonb_build_array(jsonb_build_object('forma_id',cash,'valor',30),jsonb_build_object('forma_id',credit,'valor',20)),'vencimento',(now() at time zone 'America/Bahia')::date+30);
 perform public.comanda_operation(cmd,'CLOSE',data);perform public.comanda_operation(cmd,'CLOSE',data);
 select * into sale from public.cash_sales where comanda_id=cmd;
 if sale.number<>1 or sale.nota_fiscal then raise exception 'Wrong initial sale registration or invoice default';end if;
 data:=jsonb_build_object('request_id',gen_random_uuid(),'nota_fiscal',true);
 perform public.cash_sale_operation(sale.id,'INVOICE',data);perform public.cash_sale_operation(sale.id,'INVOICE',data);
 if not (select nota_fiscal from public.cash_sales where id=sale.id) then raise exception 'Invoice flag not persisted';end if;
 perform public.comanda_operation(cmd2,'OPEN','{"identificacao":"Fixture venda dois"}');
 select * into tab from public.dining_tables where id=cmd2;
 insert into public.dining_table_items(codigo_mesa,descricao,valor_unitario,quantidade) values(tab.codigo_mesa,'Consumo',10,1);
 perform public.comanda_operation(cmd2,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',10,'payments',jsonb_build_array(jsonb_build_object('forma_id',pix,'valor',10))));
 select * into sale2 from public.cash_sales where comanda_id=cmd2;
 if sale2.number<>2 then raise exception 'Sale counter incorrect';end if;
 select p.operation_id into payment from public.comanda_payments p join public.comanda_closures cc on cc.id=p.closure_id where cc.comanda_id=cmd2;
 begin perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','estorno_de',payment,'data',(now() at time zone 'America/Bahia')::date,'descricao','Estorno direto','motivo','Teste bloqueio'));raise exception 'FAIL: cash payment reversed externally';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 select id into debit from public.customer_ledger where comanda_id=cmd and entry_type='DEBIT';
 receipt:=gen_random_uuid();
 perform public.finance_operation(receipt,jsonb_build_object('tipo','RECEIPT','valor',5,'data',(now() at time zone 'America/Bahia')::date,'descricao','Recebimento posterior','conta_id',bank,'forma_id',pix,'debito_id',debit));
 data:=jsonb_build_object('request_id',gen_random_uuid(),'motivo','Ajustar itens da venda');
 begin perform public.cash_sale_operation(sale.id,'REOPEN',data);raise exception 'FAIL: reopen debt already received';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','estorno_de',receipt,'data',(now() at time zone 'America/Bahia')::date,'descricao','Estorno recebimento','motivo','Reabrir venda'));
 result:=public.cash_sale_operation(sale.id,'REOPEN',data);perform public.cash_sale_operation(sale.id,'REOPEN',data);
 newcmd:=(result->>'comanda_id_aberta')::uuid;
 if (result->>'comanda_numero')::integer<>1 or newcmd is null then raise exception 'Reopened comanda number missing';end if;
 if (select total_geral from public.dining_tables where id=newcmd)<>50 or (select paid_total from public.dining_tables where id=newcmd)<>0 or (select status from public.dining_tables where id=newcmd)<>'aberta' then raise exception 'Reopened consumption wrong';end if;
 if (select total_pendente from public.customers where codigo_cliente=customer)<>0 then raise exception 'Debt not annulled on reopen';end if;
 if (select sum(valor) from public.financial_entries where conta_id=acc)-baseline<>95 then raise exception 'Reopen financial refund wrong';end if;
 result:=public.cash_dashboard();
 if (select (v->>'expected_cash')::numeric from jsonb_array_elements(result) v where v->>'id'=session::text)<>85 then raise exception 'Reopen physical refund wrong';end if;
 begin perform public.cash_operation(session,'CLOSE','{"contado":85,"esperado":85}');raise exception 'FAIL: cash closed with reopened sale';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 -- Finishing the reopened sale preserves the number, does not consume another number.
 perform public.comanda_operation(newcmd,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',50,'payments',jsonb_build_array(jsonb_build_object('forma_id',cash,'valor',40),jsonb_build_object('forma_id',pix,'valor',10))));
 if (select number from public.cash_sales where id=sale.id)<>1 or (select comanda_id from public.cash_sales where id=sale.id)<>newcmd or (select status from public.cash_sales where id=sale.id)<>'FINALIZED' then raise exception 'Refinalization lost original record';end if;
 data:=jsonb_build_object('request_id',gen_random_uuid(),'motivo','Venda lançada por engano');
 perform public.cash_sale_operation(sale2.id,'CANCEL',data);perform public.cash_sale_operation(sale2.id,'CANCEL',data);
 perform public.comanda_operation(cmd3,'OPEN','{"identificacao":"Fixture venda três"}');
 perform public.comanda_operation(cmd3,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',0,'payments','[]'::jsonb));
 if (select number from public.cash_sales where comanda_id=cmd3)<>3 then raise exception 'Canceled sale number reused';end if;
 begin perform public.cash_operation(session,'CLOSE','{"contado":124,"esperado":125}');raise exception 'FAIL: difference without justification';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 begin perform public.cash_operation(session,'CLOSE','{"contado":125,"esperado":126}');raise exception 'FAIL: stale close';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:='{"contado":124,"esperado":125,"motivo":"Falta na conferência"}';
 perform public.cash_operation(session,'CLOSE',data);perform public.cash_operation(session,'CLOSE',data);
 if (select difference from public.cash_sessions where id=session)<>-1 then raise exception 'Difference not saved';end if;
 begin perform public.cash_sale_operation(sale.id,'REOPEN',jsonb_build_object('request_id',gen_random_uuid(),'motivo','Reabrir caixa fechado'));raise exception 'FAIL: modified closed cash';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 begin perform public.cash_operation(session,'SUPPLY',jsonb_build_object('request_id',gen_random_uuid(),'valor',1,'conta_id',bank,'motivo','Teste fechado'));raise exception 'FAIL: supplied closed cash';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 -- A new session restarts its sequence; transfer opening money without sales income.
 perform public.cash_operation(session2,'OPEN',jsonb_build_object('conta_id',acc,'categoria_id',cat,'valor_abertura',10,'origem_id',bank));
 perform public.comanda_operation(cmd4,'OPEN','{"identificacao":"Fixture outro caixa"}');
 perform public.comanda_operation(cmd4,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',0,'payments','[]'::jsonb));
 if (select number from public.cash_sales where comanda_id=cmd4)<>1 then raise exception 'Sequence did not restart';end if;
 begin perform app_private.finance_operation_base(gen_random_uuid(),'{}');raise exception 'FAIL: unguarded finance access';exception when insufficient_privilege then null;end;
 perform set_config('app.test.cash_sale_id',sale.id::text,true);
end $$;
reset role;
update app_private.account_directory set role='OPERATOR' where email='dejandrea@gmail.com';
set local role authenticated;
do $$begin
 begin perform public.cash_sale_operation(current_setting('app.test.cash_sale_id')::uuid,'CANCEL',jsonb_build_object('request_id',gen_random_uuid(),'motivo','Operador tenta cancelar'));raise exception 'FAIL: operator canceled sale';exception when insufficient_privilege then null;end;
 begin perform public.cash_sale_operation(current_setting('app.test.cash_sale_id')::uuid,'REOPEN',jsonb_build_object('request_id',gen_random_uuid(),'motivo','Operador tenta reabrir'));raise exception 'FAIL: operator reopened sale';exception when insufficient_privilege then null;end;
end $$;
reset role;
update app_private.account_directory set role='MASTER' where email='dejandrea@gmail.com';
do $$begin
 if not exists(select 1 from app_private.operation_logs where entity='public.cash_sales' and action='UPDATE' and before_data->>'status'='FINALIZED' and after_data->>'status'='REOPENED') or not exists(select 1 from app_private.operation_logs where entity='public.cash_movements' and action='INSERT') or not exists(select 1 from app_private.operation_logs where entity='public.customer_ledger' and action='INSERT') then raise exception 'Audit logs missing';end if;
 begin delete from app_private.operation_logs where id=(select min(id) from app_private.operation_logs);raise exception 'FAIL: deleted audit log';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
end $$;
do $$begin perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);end $$;
set local role authenticated;
do $$begin
 if exists(select 1 from public.cash_sales) or exists(select 1 from public.cash_movements) then raise exception 'Unauthorized cash read';end if;
 begin perform public.cash_dashboard();raise exception 'FAIL: unauthorized dashboard';exception when insufficient_privilege then null;end;
 begin perform public.cash_sale_operation(gen_random_uuid(),'CANCEL',jsonb_build_object('request_id',gen_random_uuid(),'motivo','Tentativa'));raise exception 'FAIL: unauthorized cancellation';exception when insufficient_privilege then null;end;
 begin select count(*) from app_private.operation_logs;raise exception 'FAIL: audit logs exposed';exception when insufficient_privilege then null;end;
end $$;
rollback;
select 'cash operations passed' as result;
